// ---- src/billing.js ----
// Usage facts for New API task billing. The plugin reports quantities only;
// the administrator's expressions set every price, and no model has a price
// or a pricing rule here.
//
// Default schema (every model): input_tokens excludes cached reads and cache
// writes, so the four token fields never count a token twice; requests is 1
// for each successful request.
// An upstream that reports no tokens (Databricks ai-decide) reports requests
// only: token fields are never made up, so an expression that reads them
// fails and the request is refused instead of billed as free.
// upstream_cost is the USD amount a relay reported for the request, and is
// present only when it reported one; it lets one expression bill cost-plus.
// Special profiles (meta.usageProfiles) exist only where a model is billed
// differently for chat and for decisions: gpt-6-luna. Adding one is a new
// entry in SPECIAL_BILLING.


function tokenField(en, zh) {
  return { type: "number", unit: "token", description: { en: en, zh: zh } };
}

const COST_FIELD = {
  type: "number",
  unit: "credit",
  description: { en: "USD the upstream reported for the request (OpenRouter, ScaleDown, Eden AI, OpenCode); absent when it reports none", zh: "上游回复里报告的本次费用（美元，OpenRouter、ScaleDown、Eden AI、OpenCode 等）；上游不报告时没有这一项" },
};

const DEFAULT_SCHEMA = {
  input_tokens: tokenField("Input token unit price", "输入 token 单价"),
  cache_read_tokens: tokenField("Cached input token unit price", "缓存读取 token 单价"),
  cache_write_tokens: tokenField("Cache write token unit price", "缓存写入 token 单价"),
  output_tokens: tokenField("Output token unit price", "输出 token 单价"),
  requests: { type: "number", unit: "count", description: { en: "Successful requests (always 1); the only fact of upstreams without token usage", zh: "成功请求数（恒为 1）；无 token 用量的上游只报告这一项" } },
  upstream_cost: COST_FIELD,
};

const DEFAULT_EXAMPLES = [
  { label: "1k input", facts: { input_tokens: 1000, cache_read_tokens: 0, cache_write_tokens: 0, output_tokens: 0, requests: 1, upstream_cost: 0.00004 } },
  { label: "8k input · 2k cached", facts: { input_tokens: 6000, cache_read_tokens: 2000, cache_write_tokens: 0, output_tokens: 0, requests: 1, upstream_cost: 0.00026 } },
];

// The facts of an upstream that reports no token usage.
function requestFacts() {
  return { requests: 1 };
}

// OpenAI bills gpt-6-luna decisions for input, cached input and cache writes,
// never for output, and doubles the rates above 272K input tokens.
const LUNA_SCHEMA = {
  input_tokens: tokenField("Input token unit price", "输入 token 单价"),
  cache_read_tokens: tokenField("Cached input token unit price", "缓存读取 token 单价"),
  cache_write_tokens: tokenField("Cache write token unit price", "缓存写入 token 单价"),
  long_context: { type: "boolean", description: { en: "Input longer than 272K tokens", zh: "输入超过 272K token" } },
  upstream_cost: COST_FIELD,
};

const SPECIAL_BILLING = [
  {
    models: ["gpt-6-luna", "openai/gpt-6-luna", "openai/gpt-6-luna-decisions", "gpt-6-luna-decisions"],
    schema: LUNA_SCHEMA,
    examples: [
      { label: "1k input", facts: { input_tokens: 1000, cache_read_tokens: 0, cache_write_tokens: 0, long_context: false, upstream_cost: 0.0001 } },
      { label: "8k input · 6k cached", facts: { input_tokens: 2000, cache_read_tokens: 6000, cache_write_tokens: 0, long_context: false, upstream_cost: 0.00026 } },
      { label: "300k input", facts: { input_tokens: 300000, cache_read_tokens: 0, cache_write_tokens: 0, long_context: true, upstream_cost: 0.06 } },
    ],
    facts: function (usage) {
      return {
        input_tokens: usage.billedInput,
        cache_read_tokens: usage.cacheRead,
        cache_write_tokens: usage.cacheWrite,
        long_context: usage.input > 272000,
      };
    },
  },
];

function fold(name) {
  return String(name || "").toLowerCase();
}

// The host selects the profile of the first of (upstream model, client model)
// that a profile lists, else the default schema; this mirrors it.
function billingProfile(upstreamModel, model) {
  for (const name of [upstreamModel, model]) {
    for (const profile of SPECIAL_BILLING) {
      if (profile.models.some((declared) => fold(declared) === fold(name))) return profile;
    }
  }
  return null;
}

const MAX_FACT = 2147483647;

function clampTokens(value) {
  if (!Number.isFinite(value) || value < 0) return 0;
  return Math.min(Math.floor(value), MAX_FACT);
}

function usageFacts(usage, upstreamModel, model) {
  const input = clampTokens(usage.input);
  const cacheRead = Math.min(clampTokens(usage.cacheRead), input);
  const cacheWrite = Math.min(clampTokens(usage.cacheWrite), input - cacheRead);
  const normalized = { input: input, cacheRead: cacheRead, cacheWrite: cacheWrite, billedInput: input - cacheRead - cacheWrite, output: clampTokens(usage.output) };
  const profile = billingProfile(upstreamModel, model);
  const facts = profile
    ? profile.facts(normalized)
    : { input_tokens: normalized.billedInput, cache_read_tokens: cacheRead, cache_write_tokens: cacheWrite, output_tokens: normalized.output, requests: 1 };
  if (typeof usage.cost === "number" && Number.isFinite(usage.cost) && usage.cost >= 0) facts.upstream_cost = usage.cost;
  return facts;
}

// ---- reservation ------------------------------------------------------------
// A safe upper bound on input tokens without the vendors' tokenizers: a
// byte-level tokenizer never emits more tokens than the text has UTF-8 bytes,
// media never costs more tokens than its encoded bytes, plus a prompt
// template allowance; capped by the upstream's context limit, past which the
// upstream refuses the request anyway. Settlement replaces it with the usage
// the upstream reports.
const TEMPLATE_TOKENS = 256;
const QUESTION_TOKENS = 64;
const URL_IMAGE_TOKENS = 8192;

function contentBytes(content, files) {
  if (!content) return 0;
  let bytes = 0;
  for (const segment of content) {
    if (segment.t === "text") bytes += utf8Length(segment.text);
    else if (segment.t === "json") bytes += utf8Length(JSON.stringify(segment.value));
    else if (segment.data) bytes += base64Bytes(segment.data);
    else if (segment.fileRef) {
      const file = (files || []).find((item) => item.ref === segment.fileRef);
      bytes += file && Number.isFinite(file.size) ? file.size : Infinity;
    } else bytes += segment.kind === "image" ? URL_IMAGE_TOKENS : Infinity;
  }
  return bytes;
}

function estimateInputTokens(ir, files) {
  let total = TEMPLATE_TOKENS + contentBytes(ir.input, files);
  // Extraction field definitions are read as part of the input.
  if (ir.fields) total += utf8Length(JSON.stringify(ir.fields)) + QUESTION_TOKENS * Object.keys(ir.fields).length;
  for (const question of ir.questions) {
    total += QUESTION_TOKENS + utf8Length(question.name);
    total += contentBytes(question.instructions, files) + contentBytes(question.trueText, files) + contentBytes(question.falseText, files);
    for (const option of question.options || []) total += utf8Length(option.key) + contentBytes(option.description, files);
    for (const level of question.levels || []) total += utf8Length(level.label || "") + contentBytes(level.description, files);
  }
  return total;
}

// Decision outputs are a few tokens per question; reserve a bound for models
// whose administrator prices output.
const OUTPUT_TOKENS_PER_QUESTION = 32;

function reservationFacts(ir, files, route, longContext, upstreamModel, model) {
  if (route.upstream.noUsage) return requestFacts();
  const cap = route.reserveTokens || (longContext && route.upstream.longContextTokens) || route.upstream.contextTokens;
  const tokens = Math.min(estimateInputTokens(ir, files), cap);
  const answers = ir.questions.length || Object.keys(ir.fields || {}).length;
  return usageFacts({ input: tokens, cacheRead: 0, cacheWrite: 0, output: OUTPUT_TOKENS_PER_QUESTION * answers }, upstreamModel, model);
}

function usageFromTaskData(data) {
  if (!isObject(data) || !isObject(data.usage)) return null;
  const usage = data.usage;
  if (!Number.isInteger(usage.input) || usage.input < 0) return null;
  return usage;
}

// ---- src/plugin.js ----
// Entry module: manifest, native routes and the task driver hooks.
// Request:  client body -> client decoder -> Decision IR -> upstream encoder -> upstream
// Response: upstream reply -> upstream parser -> answers/usage IR -> client renderer


const VERSION = "1.1.0";

const LONG_CONTEXT_HEADER = "TypeSafe-Danger-Zone-Long-Context";
const IMAGES_HEADER = "TypeSafe-Danger-Zone-Images";

const DECODERS = {
  systemone: "decodeSystemOne",
  openrouter: "decodeOpenRouter",
  scaledown: "decodeScaleDown",
  decisions: "decodeDecisions",
  openai: "decodeOpenAI",
  gemini: "decodeGemini",
  vercel: "decodeEvaluate",
  databricks: "decodeDatabricks",
  extractions: "decodeExtractions",
};

export const meta = {
  apiVersion: 1,
  key: "decision",
  name: { en: "Decision", zh: "Decision 决策模型" },
  version: VERSION,
  icon: "text:DE",
  author: { name: "yiyinfaith", url: "https://github.com/yiyinfaith" },
  website: "https://github.com/yiyinfaith/new-api-plugin-decision",
  description: {
    en: "Universal decision model gateway with cross-protocol conversion, flexible model routing, custom upstream protocols, and usage-based billing",
    zh: "NewAPI 通用决策模型插件，支持多种决策协议双向转换、任意模型接入、自定义上游协议及路径、智能路由与灵活计费",
  },
  baseUrl: "https://api.typesafe.ai",
  auth: "api_key",
  models: MODELS,
  upstreams: ["vendor", "new_api"],
  // System One reads state objects as written, so member order changes answers.
  requiredCapabilities: ["json-order@1"],
  fetchMode: "per_task",
  routes: CLIENT_ROUTES.map((route) => ({ method: "POST", path: route.path, type: "submit", decode: DECODERS[route.protocol], render: "renderDecision", retainResult: false })),
  channelConfig: CHANNEL_CONFIG,
  keyHint: { en: "The upstream API key", zh: "上游 API Key" },
  usageSchema: DEFAULT_SCHEMA,
  usageExamples: DEFAULT_EXAMPLES,
  usageProfiles: SPECIAL_BILLING.map((profile) => ({ models: profile.models.filter((model) => MODELS.indexOf(model) >= 0), schema: profile.schema, examples: profile.examples })),
};

// Errors carry their status and code to the error presenter in the message,
// since hooks can only throw Error.
const ERROR_TAG = /\[decision:(\d{3}):([a-z_]+)\]\s?/;

function hookError(error) {
  const decision = toDecisionError(error);
  return new Error("[decision:" + decision.status + ":" + decision.code + "] " + decision.message);
}

function guarded(fn) {
  return function () {
    try {
      return fn.apply(null, arguments);
    } catch (error) {
      throw hookError(error);
    }
  };
}

function run(fn) {
  return guarded(fn)();
}

// The client body: JSON, or the System One SDK's multipart form with the JSON
// in a part named request and each image in its own file part.
function clientBody(body) {
  if (body && body.kind === "json") return { value: body.value, files: [] };
  if (body && body.kind === "multipart") {
    const fields = body.fields && body.fields.request;
    if (!fields || fields.length !== 1) fail("A multipart request needs one request field with the JSON request");
    let value;
    try {
      value = JSON.parse(fields[0]);
    } catch (parseError) {
      fail("The request field must hold the JSON request");
    }
    return { value: value, files: body.files || [] };
  }
  fail("JSON or multipart body required", "unsupported_media_type", 415);
}

function decodeAs(hint) {
  return guarded(function (ctx) {
    const body = clientBody(ctx.body);
    const protocol = hint === "decisions" ? clientProtocol("/v1/decisions", body.value) : hint;
    if (hasProtoKey(body.value)) fail("The request cannot use __proto__ as a name");
    if (body.files.length && CLIENTS[protocol].family !== "systemone") fail("Only System One requests may upload files as multipart parts");
    const ir = CLIENTS[protocol].decode(body.value, body.files);
    return { kind: "submit", model: ir.model, action: protocol, requestBody: { protocol: protocol, body: body.value } };
  });
}

function longContext(ctx) {
  const value = headerValue(ctx.requestHeaders, LONG_CONTEXT_HEADER);
  return typeof value === "string" && value.trim().toLowerCase() === "true";
}

// Decodes the normalized request again and resolves the channel; driver hooks
// are called several times and must not keep state between calls.
function prepare(ctx) {
  const request = ctx.requestBody;
  if (!isObject(request) || typeof request.protocol !== "string" || !hasOwn(CLIENTS, request.protocol)) fail("The task request is not a Decision request", "invalid_request", 500);
  const ir = CLIENTS[request.protocol].decode(request.body, ctx.files || []);
  const route = resolveChannel(ctx);
  if (route.maxQuestions > 0 && ir.questions.length > route.maxQuestions)
    fail(
      "This channel accepts at most " + route.maxQuestions + " questions per request and the request has " + ir.questions.length + "; split it into smaller requests",
      "limit_exceeded",
    );
  return { ir: ir, route: route, protocol: request.protocol };
}

export function buildSubmitRequest(ctx) {
  return run(() => submitRequest(ctx));
}

function submitRequest(ctx) {
  const prepared = prepare(ctx);
  const ir = prepared.ir;
  const route = prepared.route;
  const encoded = encodeUpstream(route.protocol, ir, route.model, () => utils.uuid(), { fillInstructions: route.fillInstructions, keepModel: route.keepModel, imageMode: route.imageMode });
  const headers = { Accept: "application/json" };
  for (const name of Object.keys(route.headers)) headers[name] = route.headers[name];
  if (route.upstream.family === "systemone") {
    if (encoded.images) headers[IMAGES_HEADER] = "true";
    if (longContext(ctx)) headers[LONG_CONTEXT_HEADER] = "true";
  }
  if (route.protocol === "vercel_sdk") {
    headers["ai-evaluation-model-specification-version"] = "4";
    headers["ai-gateway-protocol-version"] = "0.0.1";
    headers["ai-gateway-auth-method"] = "api-key";
    headers["ai-model-id"] = route.model;
  }
  const request = { url: route.url, method: "POST", headers: headers };
  // System One with uploaded images: the JSON goes first in a part named
  // request, then each file, as the TypeSafe SDKs send it.
  const passthroughFiles = encoded.forwardFiles ? ctx.files || [] : [];
  const parts = encoded.multipartFiles || (passthroughFiles.length ? passthroughFiles.map((file) => ({ name: file.field, fileRef: file.ref, filename: file.filename })) : null);
  if (parts) {
    request.bodyType = "multipart";
    request.parts = [{ name: "request", value: JSON.stringify(encoded.body) }].concat(parts);
    return request;
  }
  headers["Content-Type"] = "application/json";
  request.body = encoded.body;
  return request;
}

export function parseSubmitResponse(ctx, response) {
  return run(() => submitResult(ctx, response));
}

function submitResult(ctx, response) {
  if (response.statusCode < 200 || response.statusCode >= 300) fail("The upstream returned HTTP " + response.statusCode, "upstream_error", 502);
  if (!ctx.publicTaskId) fail("Missing gateway request ID", "internal_error", 500);
  const prepared = prepare(ctx);
  const result = parseUpstream(prepared.route.protocol, response.body, prepared.ir);
  const client = CLIENTS[prepared.protocol];
  const reply = passthroughReply(prepared.protocol, prepared.route.protocol, result) || client.render(prepared.ir, result, ctx.publicTaskId);
  return {
    taskId: ctx.publicTaskId,
    taskData: { response: reply, usage: result.usage, protocol: prepared.route.protocol },
    immediate: { status: "SUCCESS", progress: "100%" },
  };
}

// The host asks for billing ratios only on its per-call path, taken when the
// model has no task expression: a fixed per-call price, or a ratio, which the
// host turns into a flat charge of half the ratio in dollars per request and
// never settles by tokens. The hook cannot tell the two apart, so a token
// upstream refuses the path unless the channel accepts fixed per-call prices;
// an upstream without token usage takes the fixed per-call price as is.
function perCallRefusal(ctx) {
  const model = ctx.model;
  if (billingProfile(ctx.upstreamModel || model, model))
    return (
      "Model " + model + " has no decision price. Its model price bills chat; set the plugin price decision::" + model +
      ' with a usage expression such as tier("base", (u("input_tokens") * 0.10 + u("cache_read_tokens") * 0.01 + u("cache_write_tokens") * 0.125) / 1000000)'
    );
  return (
    "Model " + model + " is priced per call or by ratio, which cannot bill decision tokens. Set its model price to a task expression that reads the token usage, " +
    'such as tier("base", u("input_tokens") * 0.042 / 1000000), or turn on the channel\'s perCallPrice to accept a fixed per-call price'
  );
}

export function extractUsage(ctx) {
  return run(function () {
    const prepared = prepare(ctx);
    if (ctx.usagePurpose === "billing_ratios") {
      if (prepared.route.upstream.noUsage || prepared.route.perCallPrice) return null;
      fail(perCallRefusal(ctx), "model_price_error");
    }
    return reservationFacts(prepared.ir, ctx.files || [], prepared.route, longContext(ctx), ctx.upstreamModel || ctx.model, ctx.model);
  });
}

export function extractUsageOnComplete(ctx, result, data) {
  // An upstream without token usage is billed per successful request; the
  // protocol was recorded by parseSubmitResponse, never by the client.
  const upstream = isObject(data) ? own(UPSTREAMS, data.protocol) : null;
  if (upstream && upstream.noUsage) return requestFacts();
  const usage = usageFromTaskData(data);
  // A reply without usage settles as one request: a per-request price bills
  // exactly, and a token expression finds no token facts of the reply, so the
  // host settles on the reservation's. It is never billed as free.
  if (!usage) return requestFacts();
  return usageFacts(usage, ctx.upstreamModel || ctx.model, ctx.model);
}

// API v1 requires polling hooks; decisions always complete in the request.
export function buildQueryRequest() {
  throw new Error("Decision requests complete synchronously and have no task to query");
}

export function parseTaskResult() {
  return { status: "UNKNOWN", reason: "Decision requests complete synchronously" };
}

function upstreamBody(message) {
  const start = message.indexOf("{");
  if (start < 0) return null;
  try {
    const value = JSON.parse(message.slice(start));
    return isObject(value) ? value : null;
  } catch (error) {
    return null;
  }
}

function readableMessage(upstream, fallback) {
  if (!upstream) return fallback;
  if (typeof upstream.detail === "string") return upstream.detail;
  if (isObject(upstream.detail) && typeof upstream.detail.message === "string") return upstream.detail.message;
  if (isObject(upstream.error) && typeof upstream.error.message === "string") return upstream.error.message;
  // Cloudflare's API envelope.
  if (Array.isArray(upstream.errors) && isObject(upstream.errors[0]) && typeof upstream.errors[0].message === "string") return upstream.errors[0].message;
  if (typeof upstream.message === "string") return upstream.message;
  return fallback;
}

export const native = {
  decodeSystemOne: decodeAs("systemone"),
  decodeOpenRouter: decodeAs("openrouter"),
  decodeScaleDown: decodeAs("scaledown"),
  decodeDecisions: decodeAs("decisions"),
  decodeOpenAI: decodeAs("openai"),
  decodeGemini: decodeAs("gemini"),
  decodeEvaluate: decodeAs("vercel"),
  decodeDatabricks: decodeAs("databricks"),
  decodeExtractions: decodeAs("extractions"),
  renderDecision: function (ctx, task) {
    if (!isObject(task.data) || task.data.response === undefined) throw new Error("The decision result is unavailable");
    return task.data.response;
  },
  // Every error reaches the client in its own protocol's format: ours carry a
  // status tag; an upstream error body is kept when it already is in that
  // format, otherwise its message is carried over.
  error: function (ctx, error) {
    let value = null;
    try {
      value = clientBody(ctx.body).value;
    } catch (ignored) {
      value = null;
    }
    const protocol = clientProtocol(ctx.path, value) || "systemone";
    let message = String(error.message || "Request failed");
    let status = Number(error.httpStatus) || 500;
    let code = error.code || "";
    const tag = ERROR_TAG.exec(message);
    let upstream = null;
    if (tag) {
      status = Number(tag[1]);
      code = tag[2];
      message = message.replace(ERROR_TAG, "");
    } else {
      // The host may wrap an upstream error body in its own JSON error; unwrap
      // until the vendor's body is reached.
      for (let depth = 0; depth < 3; depth++) {
        const parsed = upstreamBody(message);
        if (!parsed) break;
        upstream = parsed;
        const inner = readableMessage(parsed, message);
        if (inner === message) break;
        message = inner;
      }
    }
    const body = CLIENTS[protocol].error(status, message, code, upstream);
    return { __status: status >= 400 && status <= 599 ? status : 500, __body: body };
  },
};
